package vn.covie.checkout.application; import java.security.SecureRandom; import java.util.Base64; import org.springframework.stereotype.Component; @Component public class CheckoutTokenGenerator{private final SecureRandom random=new SecureRandom();public String generate(){byte[] b=new byte[32];random.nextBytes(b);return "chk_"+Base64.getUrlEncoder().withoutPadding().encodeToString(b);}}
